// 2. Fungsi untuk menambahkan parameter ke link secara dinamis
function appendMatomoIdToLinks() {
  var savedId = localStorage.getItem('matomo_visitor_id');
  if (!savedId) return;

  // Cari semua link yang mengandung URL register DOKU
  var links = document.querySelectorAll('a[href*="dashboard.doku.com/bo/register"]');

  links.forEach(function (link) {
    try {
      var url = new URL(link.href);
      // Cek agar tidak terjadi duplikasi parameter jika script jalan berkali-kali
      if (!url.searchParams.has('matomo_visitor_id')) {
        url.searchParams.set('matomo_visitor_id', savedId);
        link.href = url.toString();
      }
    } catch (e) {
      console.error('Gagal memproses URL:', e);
    }
  });
}

// 3. Jalankan fungsi saat DOM siap dan berikan sedikit delay untuk memastikan Matomo ID sudah terambil
document.addEventListener('DOMContentLoaded', function () {
  // Jalankan segera
  appendMatomoIdToLinks();

  // Jalankan lagi setelah 1 detik untuk memastikan (fallback jika tracker lambat)
  setTimeout(appendMatomoIdToLinks, 1500);

  // Jika ada elemen yang muncul dinamis (misal dari pop-up),
  // jalankan fungsi ini saat tombol diklik (Event Delegation)
  document.addEventListener('click', function (e) {
    if (e.target.closest('a[href*="dashboard.doku.com/bo/register"]')) {
      appendMatomoIdToLinks();
    }
  });
});

(function () {
  var utmKeys = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content'];
  var params = new URLSearchParams(window.location.search);

  // Sumber internal DOKU: jangan dianggap trafik eksternal.
  // Samakan isinya dengan DOKU_INTERNAL_SOURCES di blok Google tag.
  var INTERNAL = ['dokucom', 'dokucom2', 'doku.com', 'blog', 'pr'];

  // Pembersihan satu kali: buang nilai _origin lama yang tercemar UTM internal
  var storedOrigin = (localStorage.getItem('utm_source_origin') || '').toLowerCase();
  if (storedOrigin && INTERNAL.indexOf(storedOrigin) > -1) {
    utmKeys.forEach(function (key) {
      localStorage.removeItem(key + '_origin');
    });
  }

  // Deteksi traffic eksternal: simpan UTM sebagai _origin hanya jika
  // utm_source ada dan BUKAN sumber internal
  var source = (params.get('utm_source') || '').toLowerCase();
  if (source && INTERNAL.indexOf(source) === -1) {
    utmKeys.forEach(function (key) {
      var val = params.get(key);
      if (val) {
        localStorage.setItem(key + '_origin', val);
      }
    });
  }

  // Simpan semua UTM params ke localStorage seperti biasa (tidak diubah)
  utmKeys.forEach(function (key) {
    var val = params.get(key);
    if (val) {
      localStorage.setItem(key, val);
    }
  });
})();

(function () {
  if (window.location.pathname.indexOf('contact-sales') === -1) return;

  var utmKeys = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'routeLog'];
  var queryParts = [];
  utmKeys.forEach(function (key) {
    var val = sessionStorage.getItem(key);
    if (val) queryParts.push(key + '=' + encodeURIComponent(val));
  });

  if (queryParts.length === 0) return;

  function injectUTM() {
    var iframe = document.getElementById('mf_iframe');
    if (iframe) {
      var currentSrc = iframe.src;
      if (currentSrc.indexOf('utm_source') === -1) {
        var separator = currentSrc.indexOf('?') !== -1 ? '&' : '?';
        iframe.src = currentSrc + separator + queryParts.join('&');
      }
    } else {
      setTimeout(injectUTM, 500);
    }
  }

  injectUTM();
})();

